import {warningReview,warningTaskContext} from './warning-core.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function warningDesk({getWorkspace,today,feedback}) {
  let window={from:'2026-10-01',to:today(),scope:'All'};
  const source=r=>`<article class="warning-source"><p class="small-label">${esc(r.recordKey)} / ${r.synthetic?'SYNTHETIC':'ANALYST-ENTERED / UNVERIFIED'}</p><h4>${esc(r.title)}</h4><p><strong>Known by ${r.recordedAt}</strong> · Published ${r.reportedAt}<br>${esc(r.publisher)} · Group ${esc(r.originGroup)} · ${esc(r.claimState)} / ${esc(r.relation)}</p><blockquote class="source-excerpt">${esc(r.text)}</blockquote><p>Quoted date mentions: ${r.dateMentions.dates.slice(0,6).map(s=>`“${esc(s.quote)}” [${s.start}, ${s.end})${s.year===null?' (year unspecified)':''}`).join('; ')||'None in supported formats.'}${r.dateMentions.dates.length>6?' (first six shown)':''}</p>${r.dateMentions.invalidDates.length?`<p>Invalid calendar mentions: ${r.dateMentions.invalidDates.slice(0,6).map(s=>`“${esc(s.quote)}” [${s.start}, ${s.end})`).join('; ')}</p>`:''}<p class="muted">Parser state: ${esc(r.dateMentions.dateState)}. These mentions are not confirmed event times.</p>${r.supersedesDocumentId?`<p>Correction of ${esc(r.supersedesDocumentId)} · ${esc(r.revisionNote)}</p>`:''}${r.locator?`<p>Locator: ${esc(r.locator)}</p>`:''}${r.accessNote?`<p>Source conditions: ${esc(r.accessNote)}</p>`:''}${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open source reference (unverified)</a>`:''}</article>`;
  function results() {
    const report=warningReview(getWorkspace(),window);
    document.getElementById('warning-results').innerHTML=`<div class="notice"><strong>${report.reviewCaseCount} case(s) with review gaps · ${report.recordsScanned} current records</strong><p>Applied window: ${report.window.from} to ${report.window.to} / ${esc(report.window.scope)}. All retained text is considered without keywords. Cases stay in workspace order, with no inferred severity ranking.</p></div>${report.cases.map(c=>`<article class="signal-card"><div class="case-heading"><div><p class="small-label">${esc(c.scope)} / ${esc(c.area)}</p><h3>${esc(c.title)}</h3></div><span class="chip">${c.rules.length} review reasons</span></div><p>${c.recordCount} retained records · ${c.groups.length} recorded source groups. Existing case assignment; event identity remains unverified.</p>${c.rules.map(r=>`<div class="warning-reason"><h4>${esc(r.label)} · ${r.count}</h4><p>${esc(r.reason)}</p><details><summary>Inspect triggering source references</summary><p>${r.recordKeys.slice(0,30).map(esc).join(', ')}${r.recordKeys.length>30?` · first 30 of ${r.recordKeys.length} shown`:''}</p></details></div>`).join('')||'<p>No implemented context rules triggered. This does not establish safety or absence of a threat.</p>'}<div class="actions"><button data-task-case="${esc(c.assessmentId)}">View assessment</button>${c.rules.length?`<button data-warning-followup="${esc(c.assessmentId)}">Prepare context verification task</button>`:''}<button data-open-view="intake">Review staged sources</button></div><details><summary>Inspect as-of source timeline (${c.timeline.length} of ${c.recordCount})</summary><p class="muted">Ordered by recorded date, then publication date. ${c.hiddenTimelineCount?`${c.hiddenTimelineCount} older records omitted from this display; rule counts include them.`:'All eligible current records are shown.'} Superseded sources are replaced only once their correction is known.</p>${c.timeline.map(source).join('')}</details></article>`).join('')||'<p class="empty">No retained records in this window. Missing coverage is not evidence of safety. Add permitted sources through collection or document intake.</p>'}<details><summary>Review method and limits</summary>${report.limitations.map(l=>`<p>${esc(l)}</p>`).join('')}</details>`;
  }
  function render() {
    document.getElementById('content').innerHTML=`<section class="panel"><div class="panel-heading"><div><h2>Early-warning review</h2><span class="muted">Source context → verification → reviewed evidence</span></div><button id="signal-scenario">Load fictional regional exercise</button></div><div class="case-body"><p>Review new source material and unresolved context before forming a warning. This desk automatically surfaces intake gaps, challenging evidence, repeated source groups and uncertain date mentions in current retained reports.</p><p class="notice">Rules identify verification work, not a predicted attack. No new source collection, semantic event resolution or background monitoring occurs here.</p><div class="actions"><button data-open-view="collection">Collect permitted sources</button><button data-open-view="signals">Compare reports and indicator mentions</button><button data-open-view="tasks">Open verification tasks</button></div><form id="warning-form"><div class="signal-fields"><div><label for="warning-from">Reports since</label><input id="warning-from" type="date" value="${window.from}" required></div><div><label for="warning-to">Known by</label><input id="warning-to" type="date" value="${window.to}" required></div><div><label for="warning-scope">Geographic scope</label><select id="warning-scope">${['All','Domestic','Cross-border','International'].map(s=>`<option${s===window.scope?' selected':''}>${s}</option>`).join('')}</select></div></div><p class="muted">Both publication and recorded dates must be no later than Known by. Publication must be within the selected window. Applying a window changes this view only.</p><p id="warning-error" class="error" role="alert"></p><button type="submit" class="primary">Refresh source review</button></form><div id="warning-results"></div></div></section>`;
    results();
  }
  document.addEventListener('submit',event=>{if(event.target.id!=='warning-form')return;event.preventDefault();try{const next={from:document.getElementById('warning-from').value,to:document.getElementById('warning-to').value,scope:document.getElementById('warning-scope').value};warningReview(getWorkspace(),next);window=next;results();document.getElementById('warning-error').textContent='';feedback('Source-context review refreshed. Evidence, judgments and tasks remain unchanged.');}catch(e){document.getElementById('warning-error').textContent=e.message;}});
  return {render,taskContext:id=>warningTaskContext(getWorkspace(),window,id)};
}
